"""Build the GitHub Pages laboratory for WiSig integration and simulation evidence."""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd


ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data"


def compact_records(path: Path) -> str:
    return json.dumps(pd.read_csv(path).to_dict(orient="records"), separators=(",", ":"))


def main() -> None:
    tokens = {
        "__STATUS__": json.dumps(
            json.loads((DATA / "wisig_integration_status.json").read_text(encoding="utf-8")),
            separators=(",", ":"),
        ),
        "__CELLS__": compact_records(DATA / "joint_cell_summary.csv"),
        "__PAIRS__": compact_records(DATA / "joint_paired_effects.csv"),
        "__META__": json.dumps(
            json.loads((DATA / "joint_experiment_metadata.json").read_text(encoding="utf-8")),
            separators=(",", ":"),
        ),
    }
    page = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="WiSig external real-data integration and executed joint torus-valued SSM simulation benchmark.">
<title>Signals Project · WiSig Real-Data Laboratory</title>
<script src="https://cdn.jsdelivr.net/npm/plotly.js-dist-min@2.35.2/plotly.min.js"></script>
<style>
:root{--bg:#050811;--panel:#0d1724;--line:#25384c;--ink:#e9f2fb;--muted:#9aadc1;--cyan:#35d4ff;--amber:#ffc35f;--green:#64e4aa;--violet:#ad91ff;--coral:#ff8178;--shadow:0 20px 55px rgba(0,0,0,.32)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 86% -5%,#17384f 0,transparent 29%),linear-gradient(180deg,#050811,#08131f 56%,#050811);color:var(--ink);font:15px/1.62 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--cyan)}button,select{font:inherit}.shell{max-width:1260px;margin:auto;padding:0 24px 70px}.top{position:sticky;top:0;z-index:20;background:rgba(5,8,17,.9);backdrop-filter:blur(18px);border-bottom:1px solid rgba(160,190,220,.17)}.topin{max-width:1260px;margin:auto;padding:13px 24px;display:flex;align-items:center;gap:17px}.brand{font-weight:850;letter-spacing:.04em;white-space:nowrap}.brand b{color:var(--cyan)}nav{display:flex;gap:4px;overflow:auto}.tab{border:0;background:transparent;color:var(--muted);padding:9px 11px;border-radius:9px;cursor:pointer;white-space:nowrap}.tab:hover,.tab.active{background:#142b3e;color:#fff}.toplink{margin-left:auto;text-decoration:none;border:1px solid #386479;padding:8px 12px;border-radius:9px;white-space:nowrap}.hero{padding:66px 0 34px;display:grid;grid-template-columns:1.25fr .75fr;gap:30px;align-items:end}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--cyan);font-weight:850}.hero h1{font-size:clamp(40px,6vw,74px);line-height:.98;letter-spacing:-.055em;margin:11px 0 20px}.hero p{font-size:18px;color:#bdcad7;max-width:820px}.claim{padding:18px;border:1px solid #654f27;border-left:4px solid var(--amber);background:rgba(255,195,95,.07);border-radius:0 13px 13px 0;color:#ead9b9}.claim strong{color:var(--amber)}section.view{display:none}section.view.active{display:block}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin:12px 0 27px}.card,.panel{background:linear-gradient(145deg,rgba(17,30,44,.97),rgba(9,17,27,.97));border:1px solid var(--line);box-shadow:var(--shadow);border-radius:16px}.card{padding:17px}.kval{font-size:27px;font-weight:850;letter-spacing:-.035em}.klabel{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.panel{padding:24px;margin:18px 0}.panel h2{margin:0 0 5px;font-size:25px}.panel h3{margin:4px 0 7px}.sub{color:var(--muted);margin:0 0 18px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.method{padding:19px;border:1px solid var(--line);border-radius:13px;background:rgba(5,10,17,.48)}.method p,.method li{color:#b8c5d2}.tag{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--cyan)}.status{display:inline-flex;align-items:center;gap:7px;padding:4px 9px;border-radius:999px;background:rgba(100,228,170,.11);color:var(--green);font-size:12px}.status.pending{background:rgba(255,195,95,.11);color:var(--amber)}.status.blocked{background:rgba(255,129,120,.1);color:var(--coral)}.chart{height:440px}.chart.short{height:360px}.pipeline{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.node{position:relative;min-height:155px;padding:16px;border:1px solid var(--line);border-radius:12px;background:#09131f}.node:not(:last-child):after{content:'→';position:absolute;right:-13px;top:54px;color:var(--cyan);font-size:22px;z-index:2}.node b{display:block;margin:5px 0}.node small{color:var(--muted)}.formula{font:14px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;background:#07111b;border:1px solid #25445c;border-radius:11px;padding:15px;overflow:auto;color:#d9eafa;white-space:pre-wrap}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:8px 0 14px}.control{display:grid;gap:5px;color:var(--muted);font-size:11px;letter-spacing:.09em;text-transform:uppercase}.control select{min-width:175px;color:var(--ink);background:#08111c;border:1px solid #334b63;border-radius:9px;padding:9px 12px}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{padding:10px;border-bottom:1px solid #26394d;text-align:left;vertical-align:top}th{font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}.scroll{overflow:auto}.download{display:inline-flex;text-decoration:none;color:#06111a;background:var(--cyan);font-weight:850;padding:12px 16px;border-radius:10px;margin:0 8px 9px 0}.download.secondary{background:transparent;color:var(--ink);border:1px solid #405970}.fine{font-size:12px;color:#8497aa}.footer{border-top:1px solid var(--line);margin-top:42px;padding-top:28px;color:var(--muted)}.noscript{margin:18px;padding:15px;border:1px solid var(--coral);background:#291416}@media(max-width:980px){.hero{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(3,1fr)}.pipeline{grid-template-columns:1fr 1fr}.node:after{display:none}.grid2,.grid3{grid-template-columns:1fr}.topin{flex-wrap:wrap}.toplink{margin-left:0}}@media(max-width:580px){.shell,.topin{padding-left:14px;padding-right:14px}.hero{padding-top:42px}.kpis{grid-template-columns:1fr 1fr}.pipeline{grid-template-columns:1fr}.panel{padding:16px}.chart{height:400px}.kval{font-size:23px}}
</style></head><body>
<noscript><div class="noscript">JavaScript is required for the interactive graphs. Protocols, code, CSV evidence, and the PDF remain available in the repository.</div></noscript>
<header class="top"><div class="topin"><div class="brand"><b>◉</b> SIGNALS PROJECT</div><nav aria-label="Research sections"><button class="tab active" data-view="realdata">WiSig real data</button><button class="tab" data-view="design">Benchmark design</button><button class="tab" data-view="simulation">Simulation baseline</button><button class="tab" data-view="validation">Validation</button><button class="tab" data-view="report">Report & code</button></nav><a class="toplink" href="report/Signals_Project_APA_Report.pdf">Open 27-page baseline report</a></div></header>
<main class="shell"><div class="hero"><div><div class="eyebrow">External real-data integration · computational statistics</div><h1>WiSig becomes the real-I/Q evidence lane.</h1><p>The repository now ingests non-equalized WiSig ManyRx preambles, creates deterministic two-transmitter digital overlaps, and isolates receivers and capture days before model fitting. The completed joint-torus simulation remains available as a separate baseline.</p></div><aside class="claim"><strong>Exact claim boundary</strong><br>WiSig provides hardware-captured source I/Q. Its compact recordings are not simultaneous co-channel captures and do not contain frequency-hop or channel-tap truth. The current status is <code id="heroStatus"></code>; no WiSig performance result is claimed yet.</aside></div>

<section id="realdata" class="view active"><div class="kpis"><div class="card"><div class="kval">ManyRx</div><div class="klabel">Selected subset</div></div><div class="card"><div class="kval">1.2 GB</div><div class="klabel">Reported download</div></div><div class="card"><div class="kval">256 × 2</div><div class="klabel">Samples × I/Q</div></div><div class="card"><div class="kval">25</div><div class="klabel">Pairs / Rx-day</div></div><div class="card"><div class="kval">−5 / 0 / +5</div><div class="klabel">SIR levels (dB)</div></div></div>
<div class="panel"><h2>Integration progress</h2><p class="sub">Engineering status, not model performance. The final two gates remain at zero until the official local dataset is processed and the locked test is executed.</p><div id="progressChart" class="chart short" role="img" aria-label="WiSig integration progress"></div><div class="grid3"><article class="method"><span class="status">✓ implemented</span><h3>Schema-aware loader</h3><p>Validates the official nested Tx/Rx/day/equalization structure and accepts only non-equalized 256-sample I/Q.</p></article><article class="method"><span class="status">✓ implemented</span><h3>Leakage-safe manifest</h3><p>Test receivers are unseen; validation uses a day absent from training; pairs remain inside one receiver/day domain.</p></article><article class="method"><span class="status pending">○ local data required</span><h3>Measured results</h3><p>The repository intentionally contains no fabricated WiSig scores. Aggregate endpoints appear only after the official 1.2 GB file is run.</p></article></div></div>
<div class="panel"><h2>Data provenance</h2><div class="scroll"><table><tbody><tr><th>Official dataset</th><td><a href="https://cores.ee.ucla.edu/downloads/datasets/wisig/">UCLA WiSig compact subsets</a></td></tr><tr><th>Reference code</th><td><a href="https://github.com/WiSig-dataset/wisig-examples">WiSig-dataset/wisig-examples</a></td></tr><tr><th>Selected stratum</th><td>ManyRx, non-equalized I/Q (<code>equalized=0</code>)</td></tr><tr><th>Source truth</th><td>Two original hardware-captured preambles and the deterministic SIR scale used in their digital sum</td></tr><tr><th>Not supplied</th><td>Simultaneous RF overlap, hop path, exact channel taps, LOS/MP/NLOS label, or HIL timing</td></tr><tr><th>License</th><td>WiSig data: CC BY-NC-SA 4.0; example code: BSD-3-Clause</td></tr></tbody></table></div></div></section>

<section id="design" class="view"><div class="panel"><h2>Controlled digital-overlap design</h2><p class="sub">Planned allocation per eligible receiver/day domain. These counts are construction settings, not observations or accuracy results.</p><div id="sirChart" class="chart short"></div><div class="pipeline"><div class="node"><span class="tag">1 · verify</span><b>Official ManyRx pickle</b><small>Explicit trust flag, schema validation, SHA-256 provenance.</small></div><div class="node"><span class="tag">2 · isolate</span><b>Non-equalized I/Q</b><small>Retains receiver and channel structure; 256 × 2 arrays.</small></div><div class="node"><span class="tag">3 · block</span><b>Receiver/day split</b><small>Unseen-receiver test and unseen-day validation.</small></div><div class="node"><span class="tag">4 · overlap</span><b>Two distinct Tx</b><small>Digital sum at −5, 0, or +5 dB SIR with exact components.</small></div><div class="node"><span class="tag">5 · lock</span><b>External evaluation</b><small>Freeze model, run test once, publish only aggregate evidence.</small></div></div></div>
<div class="grid2"><div class="panel"><h2>Primary real-data endpoints</h2><ul><li>Permutation-invariant component reconstruction error</li><li>Scale-invariant signal-to-distortion ratio (SI-SDR)</li><li>Mixture reconstruction and failure rate</li><li>Receiver/day-clustered confidence intervals</li></ul></div><div class="panel"><h2>Endpoints excluded from WiSig claims</h2><ul><li>Frequency-hop trajectory MSE</li><li>True phase-path RMSE</li><li>Physical channel-tap NMSE</li><li>Hardware deadline and live interception performance</li></ul></div></div><div class="panel"><h2>Exact preparation command</h2><div class="formula">PYTHONPATH=. python -m src.signals_project.wisig_realdata \
  --dataset external_data/wisig/ManyRx.pkl \
  --output external_data/derived/wisig_manyrx \
  --mixtures-per-domain 25 --seed 2026 \
  --trust-official-pickle</div><p class="fine">The raw pickle and derived I/Q are excluded from Git. Commit only checksums, manifests or aggregate results that comply with the WiSig license.</p></div></section>

<section id="simulation" class="view"><div class="panel"><h2>Frozen 2 × 3 × 3 simulation baseline</h2><p class="sub">Executed evidence retained for the hopping and latent-channel components. Select a channel to inspect frequency MSE cell means.</p><div class="controls"><label class="control">Channel<select id="channelSelect"><option>All</option><option>LOS</option><option>MP</option><option>NLOS</option></select></label></div><div id="simulationChart" class="chart"></div></div><div class="kpis"><div class="card"><div class="kval">1,800</div><div class="klabel">Method runs</div></div><div class="card"><div class="kval">900</div><div class="klabel">Paired trajectories</div></div><div class="card"><div class="kval">18</div><div class="klabel">Factorial cells</div></div><div class="card"><div class="kval">64</div><div class="klabel">Particles</div></div><div class="card"><div class="kval">27 pages</div><div class="klabel">Baseline report</div></div></div><div class="panel"><h2>Population architecture contrast</h2><div id="contrastChart" class="chart short"></div><p class="fine">Surrogate minus analytical frequency MSE; confidence interval from all paired simulated trajectories. This chart is not a WiSig result.</p></div></section>

<section id="validation" class="view"><div class="panel"><h2>Validation ladder</h2><div class="grid3"><article class="method"><span class="status">✓ complete</span><h3>Numerical and simulation</h3><p>Exact convolution quadrature, flat-torus proposal density, score checks, blind API audit, and complete factorial execution.</p></article><article class="method"><span class="status pending">○ pending execution</span><h3>WiSig external real data</h3><p>Adapter, manifests, splits, and endpoints are implemented. The official local dataset and locked aggregate run are still required.</p></article><article class="method"><span class="status blocked">○ not supplied</span><h3>Operational / HIL</h3><p>Requires a separately authorized simultaneous capture, calibrated hardware timing, blinded truth, frozen code, and independent replication.</p></article></div></div><div class="panel"><h2>Claim audit</h2><div class="scroll"><table><tbody><tr><th>Supported now</th><td>Executed broader joint torus SSM in simulation; public WiSig ingestion and leakage-safe digital-overlap protocol implemented.</td></tr><tr><th>Supported after WiSig run</th><td>External evaluation on digitally overlapped hardware-captured public I/Q across held-out receivers and days.</td></tr><tr><th>Not supported by WiSig</th><td>Simultaneous over-the-air co-channel capture, hopping validation, physical channel truth, HIL validation, or operational SIGINT performance.</td></tr></tbody></table></div></div></section>

<section id="report" class="view"><div class="panel"><h2>Report, protocol, code, and evidence</h2><p class="sub">The PDF documents the completed simulation baseline. The WiSig protocol is the controlling specification for the new external lane until real-data results exist.</p><a class="download" href="report/Signals_Project_APA_Report.pdf">Open 27-page baseline report</a><a class="download secondary" href="docs/WISIG_REAL_DATA_PROTOCOL.md">WiSig protocol</a><a class="download secondary" href="data/wisig_integration_status.json">Integration status</a><a class="download secondary" href="data/joint_factorial_results.csv">Simulation runs</a><a class="download secondary" href="https://github.com/salemmorelli1/Signals-Project">GitHub repository</a></div><div class="grid2"><div class="panel"><h2>Permanent tests</h2><ul><li>WiSig compact-schema validation</li><li>Receiver/day split disjointness</li><li>Deterministic distinct-transmitter pairing</li><li>Exact component-sum identity and requested SIR</li><li>Existing convolution, torus, score, and blind-filter tests</li></ul></div><div class="panel"><h2>Machine-readable status</h2><div class="scroll"><table><tbody><tr><th>Dataset</th><td id="statusDataset"></td></tr><tr><th>Status</th><td id="statusState"></td></tr><tr><th>Real-data executed</th><td id="statusExecuted"></td></tr><tr><th>Simulation rows</th><td id="simulationRows"></td></tr></tbody></table></div></div></div></section>
<footer class="footer">Signals Project · WiSig real-I/Q integration with an executed joint-torus simulation baseline · No operational SIGINT claim.</footer></main>
<script>
const status=__STATUS__,cells=__CELLS__,pairs=__PAIRS__,meta=__META__;
const plotBase={paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#c8d4df',family:'Inter,system-ui,sans-serif'},margin:{l:72,r:28,t:28,b:58},xaxis:{gridcolor:'#25384c',zerolinecolor:'#3b536b'},yaxis:{gridcolor:'#25384c',zerolinecolor:'#3b536b'},legend:{orientation:'h',y:1.15}};
const config={responsive:true,displaylogo:false,modeBarButtonsToRemove:['lasso2d','select2d']};
document.querySelectorAll('.tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('section.view').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.getElementById(button.dataset.view).classList.add('active');setTimeout(()=>window.dispatchEvent(new Event('resize')),40)}));
document.getElementById('heroStatus').textContent=status.status;document.getElementById('statusDataset').textContent=status.dataset;document.getElementById('statusState').textContent=status.status;document.getElementById('statusExecuted').textContent=String(status.real_data_executed);document.getElementById('simulationRows').textContent=meta.experimental_rows.toLocaleString();
Plotly.newPlot('progressChart',[{type:'bar',orientation:'h',x:[100,100,100,0,0],y:['Source selected','Adapter + tests','Protocol + split','Dataset prepared','Locked model run'],marker:{color:['#64e4aa','#64e4aa','#64e4aa','#ffc35f','#ffc35f']},text:['complete','complete','complete','awaiting 1.2 GB file','not executed'],textposition:'auto',hovertemplate:'%{y}: %{text}<extra></extra>'}],{...plotBase,height:360,xaxis:{...plotBase.xaxis,title:'Completion (%)',range:[0,100]},yaxis:{...plotBase.yaxis,automargin:true}},config);
Plotly.newPlot('sirChart',[{type:'bar',x:['−5 dB','0 dB','+5 dB'],y:[9,8,8],marker:{color:['#ff8178','#ad91ff','#35d4ff']},text:[9,8,8],textposition:'outside',hovertemplate:'%{x}<br>%{y} digital pairs per eligible domain<extra></extra>'}],{...plotBase,height:360,xaxis:{...plotBase.xaxis,title:'Target SIR'},yaxis:{...plotBase.yaxis,title:'Planned pairs per receiver/day domain',range:[0,10]}},config);
const methods=['Analytical joint score','Amortized joint surrogate'];const colors={'Analytical joint score':'#35d4ff','Amortized joint surrogate':'#ffc35f'};
function aggregate(method,snr,channel){const rows=cells.filter(x=>x.architecture===method&&x.snr_db===snr&&(channel==='All'||x.channel===channel));const n=rows.reduce((s,x)=>s+x.n,0);const mu=rows.reduce((s,x)=>s+x.mse_frequency_mean*x.n,0)/n;const sd=Math.sqrt(rows.reduce((s,x)=>s+x.mse_frequency_sd*x.mse_frequency_sd*x.n,0)/n);return {mu,se:sd/Math.sqrt(n)}}
function updateSimulation(){const channel=document.getElementById('channelSelect').value;const traces=methods.map(method=>{const rows=[-5,5,15].map(snr=>aggregate(method,snr,channel));return {type:'scatter',mode:'lines+markers',name:method,x:[-5,5,15],y:rows.map(x=>x.mu),error_y:{type:'data',array:rows.map(x=>1.96*x.se)},line:{color:colors[method],width:3},marker:{size:9},hovertemplate:'%{x} dB<br>%{y:.2f} Hz²<extra>%{fullData.name}</extra>'}});Plotly.react('simulationChart',traces,{...plotBase,xaxis:{...plotBase.xaxis,title:'Nominal simulation SNR (dB)',tickvals:[-5,5,15]},yaxis:{...plotBase.yaxis,title:'Frequency MSE (Hz²)'}},config)}
document.getElementById('channelSelect').addEventListener('change',updateSimulation);updateSimulation();
const paired=pairs.find(x=>x.group==='Overall'&&x.metric==='mse_frequency');Plotly.newPlot('contrastChart',[{type:'scatter',mode:'markers',x:[paired.mean_difference_surrogate_minus_analytical],y:['All simulated trajectories'],error_x:{type:'data',symmetric:false,array:[paired.ci95_high-paired.mean_difference_surrogate_minus_analytical],arrayminus:[paired.mean_difference_surrogate_minus_analytical-paired.ci95_low]},marker:{color:'#ad91ff',size:13},hovertemplate:'difference=%{x:.2f} Hz²<extra></extra>'}],{...plotBase,height:360,xaxis:{...plotBase.xaxis,title:'Surrogate − analytical frequency MSE (Hz²)'},yaxis:{...plotBase.yaxis},shapes:[{type:'line',x0:0,x1:0,y0:-.5,y1:.5,line:{color:'#91a3b5',dash:'dot'}}]},config);
</script></body></html>'''
    for token, value in tokens.items():
        page = page.replace(token, value)
    (ROOT / "index.html").write_text(page, encoding="utf-8")


if __name__ == "__main__":
    main()
